"namespace BCSMS.Domain.Common;

/// <summary>
/// Base class for all domain entities providing identity and audit timestamps.
/// </summary>
public abstract class BaseEntity
{
    public Guid Id { get; private set; }
    public DateTime CreatedAt { get; private set; }
    public DateTime? UpdatedAt { get; protected set; }

    protected BaseEntity()
    {
        // For EF Core materialization
    }

    protected BaseEntity(Guid id)
    {
        if (id == Guid.Empty)
            throw new ArgumentException("Entity Id cannot be empty.", nameof(id));

        Id = id;
        CreatedAt = DateTime.UtcNow;
    }
}
"

"namespace BCSMS.Domain.Common;

/// <summary>
/// Exception thrown when a domain business rule is violated.
/// Intended to be caught at the API layer and mapped to HTTP 400/422.
/// </summary>
public class DomainException : Exception
{
    public DomainException(string message)
        : base(message)
    {
    }

    public DomainException(string message, Exception innerException)
        : base(message, innerException)
    {
    }
}
"

"namespace BCSMS.Domain.Enums;

/// <summary>
/// Represents the lifecycle status of a service request.
/// </summary>
public enum RequestStatus
{
    New = 0,
    Reviewing = 1,
    Assigned = 2,
    InProgress = 3,
    Resolved = 4,
    Closed = 5,
    Rejected = 6,
    Cancelled = 7
}
"

"namespace BCSMS.Domain.Enums;

/// <summary>
/// Categories of municipal service requests.
