public enum RequestCategory
{
    RoadDamage = 0,
    WasteCleaning = 1,
    StreetLighting = 2,
    ParkGarden = 3,
    Flooding = 4,
    NoiseComplaint = 5,
    SocialAssistance = 6,
    Other = 7
}
"

"namespace BCSMS.Domain.Enums;

/// <summary>
/// Priority levels for service requests.
/// </summary>
public enum Priority
{
    Low = 0,
    Medium = 1,
    High = 2,
    Critical = 3
}
"

"namespace BCSMS.Domain.Enums;

/// <summary>
/// System user roles determining authorization scope.
/// </summary>
public enum UserRole
{
    Citizen = 0,
    Employee = 1,
    Manager = 2,
    Admin = 3
}
"

"using BCSMS.Domain.Common;

namespace BCSMS.Domain.ValueObjects;

/// <summary>
/// Represents a geographic location with coordinates and an optional human-readable address.
/// </summary>
public record Location
{
    public double Latitude { get; }
    public double Longitude { get; }
    public string? AddressText { get; }

    public Location(double latitude, double longitude, string? addressText = null)
    {
        if (latitude < -90 || latitude > 90)
            throw new DomainException($"Latitude must be between -90 and 90. Got: {latitude}");

        if (longitude < -180 || longitude > 180)
            throw new DomainException($"Longitude must be between -180 and 180. Got: {longitude}");

        Latitude = latitude;
        Longitude = longitude;
        AddressText = addressText;
    }
}
"

"using BCSMS.Domain.Common;

namespace BCSMS.Domain.ValueObjects;

/// <summary>
/// Represents a person's full name.
/// </summary>
public record FullName
{
    public string FirstName { get; }
    public string LastName { get; }

    public FullName(string firstName, string lastName)
    {
        if (string.IsNullOrWhiteSpace(firstName))
            throw new DomainException("First name is required.");

        if (string.IsNullOrWhiteSpace(lastName))
            throw new DomainException("Last name is required.");

        FirstName = firstName.Trim();
        LastName = lastName.Trim();
    }

    public override string ToString() => $"{FirstName} {LastName}";
}
"

"using BCSMS.Domain.Common;

namespace BCSMS.Domain.ValueObjects;

/// <summary>
/// Represents a user's contact information.
/// </summary>
public record ContactInfo
{
    public string Email { get; }
    public string PhoneNumber { get; }

    public ContactInfo(string email, string phoneNumber)
    {
        if (string.IsNullOrWhiteSpace(email))
            throw new DomainException("Email is required.");

        Email = email.Trim().ToLowerInvariant();
        PhoneNumber = phoneNumber?.Trim() ?? string.Empty;
    }
}
"

"using BCSMS.Domain.Common;

namespace BCSMS.Domain.Entities;

/// <summary>
/// Represents a municipal department responsible for handling service requests.
/// Aggregate root.
/// </summary>
public class Department : BaseEntity
{
    public string Name { get; private set; } = default!;
    public string? Description { get; private set; }
    public bool IsActive { get; private set; }

    private Department() : base()
    {
        // For EF Core
    }

    public Department(Guid id, string name, string? description = null)
        : base(id)
    {
        SetName(name);
        Description = description?.Trim();
        IsActive = true;
    }

    /// <summary>
    /// Updates the department's name and description.
    /// </summary>
    public void Update(string name, string? description)
    {
        SetName(name);
        Description = description?.Trim();
        UpdatedAt = DateTime.UtcNow;
    }

    public void Activate()
    {
        IsActive = true;
        UpdatedAt = DateTime.UtcNow;
    }

    public void Deactivate()
    {
        IsActive = false;
        UpdatedAt = DateTime.UtcNow;
    }

    private void SetName(string name)
    {
        if (string.IsNullOrWhiteSpace(name))
            throw new DomainException("Department name is required.");

        Name = name.Trim();
    }
}
"

"using BCSMS.Domain.Common;
using BCSMS.Domain.Enums;

namespace BCSMS.Domain.Entities;

/// <summary>
/// Records a single status transition on a service request.
/// Child entity of the ServiceRequest aggregate — cannot be created externally.
/// </summary>
public class StatusHistoryEntry : BaseEntity
{
    public Guid ServiceRequestId { get; private set; }
    public RequestStatus OldStatus { get; private set; }
    public RequestStatus NewStatus { get; private set; }
    public string? Note { get; private set; }
    public Guid ChangedByUserId { get; private set; }
    public DateTime ChangedAt { get; private set; }

    private StatusHistoryEntry() : base()
    {
        // For EF Core
    }

    internal StatusHistoryEntry(
        Guid id,
        Guid serviceRequestId,
        RequestStatus oldStatus,
        RequestStatus newStatus,
        Guid changedByUserId,
        string? note = null)
        : base(id)
    {
        ServiceRequestId = serviceRequestId;
        OldStatus = oldStatus;
        NewStatus = newStatus;
        ChangedByUserId = changedByUserId;
        Note = note?.Trim();
        ChangedAt = DateTime.UtcNow;
    }
}
"

"using BCSMS.Domain.Common;

namespace BCSMS.Domain.Entities;

/// <summary>
/// A comment or note attached to a service request.
/// Child entity of the ServiceRequest aggregate — cannot be created externally.
/// </summary>
public class Comment : BaseEntity
{
    public Guid ServiceRequestId { get; private set; }
    public string Content { get; private set; } = default!;
    public Guid CreatedByUserId { get; private set; }

    private Comment() : base()
    {
        // For EF Core
    }

    internal Comment(Guid id, Guid serviceRequestId, string content, Guid createdByUserId)
        : base(id)
    {
        if (string.IsNullOrWhiteSpace(content))
            throw new DomainException("Comment content is required.");

        ServiceRequestId = serviceRequestId;
        Content = content.Trim();
        CreatedByUserId = createdByUserId;
    }
}
"

"using BCSMS.Domain.Common;

namespace BCSMS.Domain.Entities;

/// <summary>
/// Metadata for a file attached to a service request.
/// The actual file is stored by Infrastructure — the domain only tracks metadata.
/// Child entity of the ServiceRequest aggregate — cannot be created externally.
/// </summary>
public class Attachment : BaseEntity
{
    public Guid ServiceRequestId { get; private set; }
    public string FileName { get; private set; } = default!;
    public string ContentType { get; private set; } = default!;
    public long FileSizeInBytes { get; private set; }
    public string StoragePath { get; private set; } = default!;
    public Guid UploadedByUserId { get; private set; }
    public DateTime UploadedAt { get; private set; }

    private Attachment() : base()
    {
        // For EF Core
    }

    internal Attachment(
        Guid id,
        Guid serviceRequestId,
        string fileName,
        string contentType,
        long fileSizeInBytes,
        string storagePath,
        Guid uploadedByUserId)
        : base(id)
    {
        if (string.IsNullOrWhiteSpace(fileName))
            throw new DomainException("Attachment file name is required.");

        if (string.IsNullOrWhiteSpace(contentType))
            throw new DomainException("Attachment content type is required.");

        if (fileSizeInBytes <= 0)
            throw new DomainException("Attachment file size must be greater than zero.");

        if (string.IsNullOrWhiteSpace(storagePath))
            throw new DomainException("Attachment storage path is required.");

        ServiceRequestId = serviceRequestId;
        FileName = fileName.Trim();
        ContentType = contentType.Trim();
        FileSizeInBytes = fileSizeInBytes;
        StoragePath = storagePath.Trim();
        UploadedByUserId = uploadedByUserId;
        UploadedAt = DateTime.UtcNow;
    }
}
"

